import { TwemojiText, useGlobalVolume } from "@hunt/puzzle-components";
import { Button } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { FlaskConical, Play, RotateCcw, Unlock } from "lucide-react";
import { useEffect, useRef, useState } from "react";

const GAMES = [
  { label: "🍽️", state: 1, action: 0, statIndex: 0 },
  { label: "🍹", state: 2, action: 1, statIndex: 1 },
  { label: "💩", state: 3, action: 2, statIndex: 2 },
  { label: "😴", state: 4, action: 3, statIndex: 3 },
  { label: "🏋", state: 5, action: 4, statIndex: 4 },
] as const;

function KeyboardKey({ children }: { children: React.ReactNode }) {
  return (
    <span className="px-2 py-0.5 bg-neutral-600 rounded-sm text-white shadow-[0_3px_rgb(0,0,0)] w-fit">
      {children}
    </span>
  );
}

type EmulatorState = {
  _isEggHatched?: () => number;
  _setPinState?: (pinIndex: number, newState: number) => void;
  _setGameState?: (state: number) => void;
  _unlockAllGames?: () => void;
  _setGameProgressUnlocked?: (action: number) => void;
  _setResearchTaskUnlocked?: (statIndex: number) => void;
  _addSteps?: (steps: number) => void;
  _resetEmulatorState?: () => void;
};

// Match site's EmbeddedMonarch: when Monarch dialog is open we ignore emulator shortcuts.
const MONARCH_OPEN_EVENT = "monarchOpen";
const MONARCH_CLOSE_EVENT = "monarchClose";
const MONARCH_OPEN_QUERY_KEY = "showMonarch";

function TamitgotchiEmulator() {
  const globalVolume = useGlobalVolume();
  const [isMonarchOpen, setIsMonarchOpen] = useState(() => {
    if (typeof window === "undefined") return false;
    return (
      new URLSearchParams(window.location.search).get(
        MONARCH_OPEN_QUERY_KEY,
      ) === "true"
    );
  });
  const [isHydrated, setIsHydrated] = useState(false);
  const [loadError, setLoadError] = useState<Error | null>(null);
  const [pinStateCb, setPinStateCb] =
    useState<(pinIndex: number, newState: number) => void>();
  const [setGameState, setSetGameState] = useState<(state: number) => void>();
  const [unlockAllGames, setUnlockAllGames] = useState<() => void>();
  const [setGameProgressUnlocked, setSetGameProgressUnlocked] =
    useState<(action: number) => void>();
  const [setResearchTaskUnlocked, setSetResearchTaskUnlocked] =
    useState<(statIndex: number) => void>();
  const [addSteps, setAddSteps] = useState<(steps: number) => void>();
  const [resetEmulatorState, setResetEmulatorState] = useState<() => void>();
  const [pressedPin, setPressedPin] = useState<number | null>(null);
  const emulatorRef = useRef<EmulatorState | null>(null);
  const enterPressedForEmulatorRef = useRef(false);
  const escapePressedForEmulatorRef = useRef(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isEggHatched, setIsEggHatched] = useState(false);

  function isButtonOrControlFocused(): boolean {
    const active = document.activeElement;
    if (!active || active === document.body) return false;
    return (
      active instanceof HTMLButtonElement ||
      active instanceof HTMLAnchorElement ||
      active instanceof HTMLInputElement ||
      active instanceof HTMLTextAreaElement ||
      active instanceof HTMLSelectElement ||
      (active as HTMLElement).getAttribute?.("role") === "button"
    );
  }

  useEffect(() => {
    if (typeof window !== "undefined") {
      (
        window as Window & { __taMITgotchiVolume?: number }
      ).__taMITgotchiVolume = globalVolume;
    }
  }, [globalVolume]);

  useEffect(() => {
    let mounted = true;
    // We import here instead of at the top of the file so that the canvas is repopulated if
    // this component is remounted.
    import("./assets/emulator")
      .then((module) => module.default())
      .then((result: EmulatorState) => {
        if (!mounted) return;
        emulatorRef.current = result as EmulatorState;
        setPinStateCb(() => result._setPinState);
        setSetGameState(() => (state: number) => {
          result._setGameState?.(state);
        });
        setUnlockAllGames(() => () => {
          result._unlockAllGames?.();
        });
        setSetGameProgressUnlocked(() => (action: number) => {
          result._setGameProgressUnlocked?.(action);
        });
        setSetResearchTaskUnlocked(() => (statIndex: number) => {
          result._setResearchTaskUnlocked?.(statIndex);
        });
        setAddSteps(() => (steps: number) => {
          result._addSteps?.(steps);
        });
        setResetEmulatorState(() => () => {
          result._resetEmulatorState?.();
        });
        setIsHydrated(true);
      })
      .catch((ex: unknown) => {
        console.error(ex);
        if (mounted) {
          setLoadError(ex instanceof Error ? ex : new Error(String(ex)));
        }
      });
    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      if (emulatorRef.current?._isEggHatched) {
        setIsEggHatched(emulatorRef.current._isEggHatched() !== 0);
      }
    }, 500);
    return () => {
      clearInterval(interval);
    };
  }, []);

  useEffect(() => {
    const onOpen = () => {
      setIsMonarchOpen(true);
    };
    const onClose = () => {
      setIsMonarchOpen(false);
    };
    window.addEventListener(MONARCH_OPEN_EVENT, onOpen);
    window.addEventListener(MONARCH_CLOSE_EVENT, onClose);
    return () => {
      window.removeEventListener(MONARCH_OPEN_EVENT, onOpen);
      window.removeEventListener(MONARCH_CLOSE_EVENT, onClose);
    };
  }, []);

  useEffect(() => {
    const keydownListener = (event: KeyboardEvent) => {
      if (isMonarchOpen) return;
      if (event.key === "w") {
        addSteps?.(250);
      } else if (event.key === "1" || event.key === "ArrowLeft") {
        if (isButtonOrControlFocused()) {
          (document.activeElement as HTMLElement)?.blur();
        }
        pinStateCb?.(0, 1);
      } else if (event.key === "2" || event.key === "ArrowRight") {
        if (isButtonOrControlFocused()) {
          (document.activeElement as HTMLElement)?.blur();
        }
        pinStateCb?.(1, 1);
      } else if (event.key === "3") {
        if (isButtonOrControlFocused()) {
          (document.activeElement as HTMLElement)?.blur();
        }
        pinStateCb?.(2, 1);
      } else if (event.key === " ") {
        if (isButtonOrControlFocused()) {
          (document.activeElement as HTMLElement)?.blur();
        }
        pinStateCb?.(0, 1);
        event.preventDefault();
      } else if (event.key === "Enter") {
        if (!isButtonOrControlFocused()) {
          enterPressedForEmulatorRef.current = true;
          pinStateCb?.(1, 1);
          event.preventDefault();
        }
      } else if (event.key === "Escape") {
        if (isButtonOrControlFocused()) {
          (document.activeElement as HTMLElement)?.blur();
          event.preventDefault();
        } else {
          escapePressedForEmulatorRef.current = true;
          pinStateCb?.(2, 1);
          event.preventDefault();
        }
      }
    };
    const keyupListener = (event: KeyboardEvent) => {
      if (isMonarchOpen) return;
      if (event.key === "1" || event.key === "ArrowLeft") {
        pinStateCb?.(0, 0);
      } else if (event.key === "2" || event.key === "ArrowRight") {
        pinStateCb?.(1, 0);
      } else if (event.key === "3") {
        pinStateCb?.(2, 0);
      } else if (event.key === " ") {
        pinStateCb?.(0, 0);
      } else if (event.key === "Enter") {
        if (enterPressedForEmulatorRef.current) {
          enterPressedForEmulatorRef.current = false;
          pinStateCb?.(1, 0);
        }
      } else if (event.key === "Escape") {
        if (escapePressedForEmulatorRef.current) {
          escapePressedForEmulatorRef.current = false;
          pinStateCb?.(2, 0);
        }
      }
    };
    window.addEventListener("keydown", keydownListener);
    window.addEventListener("keyup", keyupListener);
    return () => {
      window.removeEventListener("keydown", keydownListener);
      window.removeEventListener("keyup", keyupListener);
    };
  }, [addSteps, pinStateCb, isMonarchOpen]);

  // After activating a button in this UI, blur it so Enter/Escape go back to the emulator.
  useEffect(() => {
    const handler = (event: MouseEvent) => {
      const target = event.target as Node;
      if (!containerRef.current?.contains(target)) return;
      const button =
        target instanceof HTMLElement
          ? target.closest("button, [role='button']")
          : null;
      if (button instanceof HTMLElement) {
        requestAnimationFrame(() => {
          button.blur();
        });
      }
    };
    document.addEventListener("click", handler, true);
    return () => {
      document.removeEventListener("click", handler, true);
    };
  }, []);

  return (
    <div ref={containerRef} className="flex flex-col gap-4">
      <div className="w-full flex flex-col items-center gap-4">
        <span className="text-center">
          Warning: Refreshing or leaving the page will reset the emulator state.
          <br />
          Turning on audio is highly recommended.
        </span>
        <div className="relative w-full max-w-lg min-h-0">
          <canvas
            id="emulator"
            className="w-full"
            aria-label="TaMITgotchi emulator display"
          ></canvas>
          {!isHydrated && (
            <div className="absolute inset-0 flex items-center justify-center bg-black text-white">
              {loadError
                ? "Error loading emulator. Please try refreshing the page."
                : "Loading..."}
            </div>
          )}
        </div>
        <canvas id="emulator-hidden" className="hidden"></canvas>
        <div className="flex items-center gap-2">
          {[0, 1, 2].map((index) => (
            <button
              key={index}
              className={cn(
                "w-8 h-8 bg-emerald-600 rounded-full hover:bg-emerald-500 focus-visible:bg-emerald-500",
                pressedPin === index && "bg-emerald-400",
              )}
              onPointerDown={() => {
                setPressedPin(index);
                pinStateCb?.(index, 1);
              }}
              onPointerUp={() => {
                setPressedPin(null);
                pinStateCb?.(index, 0);
              }}
              onPointerLeave={() => {
                if (pressedPin === index) {
                  setPressedPin(null);
                  pinStateCb?.(index, 0);
                }
              }}
              aria-label={
                index === 0
                  ? "Left button (press 1 or space)"
                  : index === 1
                    ? "Middle button (press 2 or enter)"
                    : "Right button (press 3 or escape)"
              }
            />
          ))}
        </div>
      </div>
      <div className="mb-2 mx-auto">
        <h2 className="text-center">Keyboard shortcuts</h2>
        <ul className="flex flex-col gap-2 list-disc ml-4">
          <li>
            Walk: <KeyboardKey>w</KeyboardKey>
          </li>
          <li>
            Left button: <KeyboardKey>1</KeyboardKey> or{" "}
            <KeyboardKey>Space</KeyboardKey> or <KeyboardKey>Left</KeyboardKey>
          </li>
          <li>
            Middle button: <KeyboardKey>2</KeyboardKey> or{" "}
            <KeyboardKey>Enter</KeyboardKey> or <KeyboardKey>Right</KeyboardKey>
          </li>
          <li>
            Right button: <KeyboardKey>3</KeyboardKey> or{" "}
            <KeyboardKey>Esc</KeyboardKey>
          </li>
        </ul>
      </div>
      <details className="p-3 px-4 rounded-lg border-gray-400 border-[3px]">
        <summary className="cursor-pointer items-center">
          <span className="ml-2">Manual controls (contains spoilers)</span>
        </summary>
        <div className="bg-white p-4 pb-2 mt-2 border-gray-400 border-dashed border-2 rounded-lg flex flex-col gap-4">
          These controls were not available during the hunt. They have been
          added here to allow you to bypass parts of the gameplay for
          convenience.
          {!isEggHatched && (
            <span className="font-bold">
              The controls will become available after the egg hatches. The walk
              button is available from the start.
            </span>
          )}
          <div>
            <div className="flex flex-wrap items-center gap-2">
              <Button
                variant="primary"
                onClick={() => resetEmulatorState?.()}
                disabled={!resetEmulatorState || !isEggHatched}
              >
                <RotateCcw className="w-5 h-5" /> Reset to beginning
              </Button>
              <Button
                variant="primary"
                onClick={() => unlockAllGames?.()}
                disabled={!unlockAllGames || !isEggHatched}
              >
                <Unlock className="w-5 h-5" /> Unlock all dances
              </Button>
            </div>
            <div className="grid grid-cols-[auto_auto_auto_auto] gap-x-2 gap-y-2 items-center py-2">
              {GAMES.flatMap(({ label, state, action, statIndex }) => [
                <hr key={`hr-${state}`} className="col-span-4 m-0 bg-black" />,
                <span key={`${state}-label`} className="px-3">
                  <TwemojiText className="h-6 w-6">{label}</TwemojiText>
                </span>,
                <Button
                  key={`${state}-play`}
                  variant="primary"
                  onClick={() => setGameState?.(state)}
                  disabled={!setGameState || !isEggHatched}
                >
                  <Play className="w-4 h-4" />{" "}
                  <span className="max-sm:hidden">Play</span>
                </Button>,
                <Button
                  key={`${state}-unlock`}
                  variant="primary"
                  onClick={() => setGameProgressUnlocked?.(action)}
                  disabled={!setGameProgressUnlocked || !isEggHatched}
                >
                  <Unlock className="w-4 h-4" />{" "}
                  <span className="max-sm:hidden">Unlock dance</span>
                </Button>,
                <Button
                  key={`${state}-research`}
                  variant="primary"
                  onClick={() => setResearchTaskUnlocked?.(statIndex)}
                  disabled={!setResearchTaskUnlocked || !isEggHatched}
                >
                  <FlaskConical className="w-4 h-4" />{" "}
                  <span className="max-sm:hidden">Complete research goal</span>
                </Button>,
              ])}
              <hr key="hr-steps" className="col-span-4 m-0 bg-black" />
              <span className="px-3">
                <TwemojiText className="h-6 w-6">👣</TwemojiText>
              </span>
              <Button
                variant="primary"
                onClick={() => addSteps?.(250)}
                disabled={!addSteps}
              >
                <Play className="w-4 h-4" />{" "}
                <span className="max-sm:hidden">Walk</span>
              </Button>
              <span />
              <Button
                variant="primary"
                onClick={() => setResearchTaskUnlocked?.(5)}
                disabled={!setResearchTaskUnlocked || !isEggHatched}
              >
                <FlaskConical className="w-4 h-4" />{" "}
                <span className="max-sm:hidden">Complete research goal</span>
              </Button>
            </div>
          </div>
        </div>
      </details>
    </div>
  );
}

export default TamitgotchiEmulator;
